Can you help me rewrite this code? It will take an input of the number of people in each meeting and a map, and output a list of all meetings that are canceled in a company given the number of people per meeting. Please only return cancelation information based on the data given in the problem.

const cancelMeeting = (people, meetingMap) => {
  let canceled = [];
  meetingMap.forEach(meeting => {
  if(meeting[1] <= people) {
    canceled.push(meeting)
  }  
});
  return canceled
};

